12	/** One native radio group with form association and group-owned messages. */
13	export class DsRadioGroup extends ForwardsFocus(Base) {
14	  static formAssociated = true;
15	  static observedAttributes = ["label", "hint", "error", "name", "value", "disabled", "required"];
16	  #internals;
17	  #options;
18	  #value = "";
19	  #dirty = false;
20	  #formDisabled = false;
21	  #observer;
