23	  constructor() {
24	    super();
25	    this.#internals = this.attachInternals();
26	    const root = this.attachShadow({ mode: "open" });
27	    root.adoptedStyleSheets = [styleSheet()];
28	    root.innerHTML = `<div class="field" part="field">
29	      <div id="label" class="label" part="label"></div>
30	      <div class="options" part="options" role="radiogroup" aria-labelledby="label"></div>
31	      <p id="hint" class="hint" part="hint" hidden></p>
32	      <p id="error" class="error" part="error" hidden aria-live="polite"></p>
33	    </div>`;
34	    this.#options = root.querySelector(".options");
35	    this.#options.addEventListener("change", (event) => {
36	      this.#dirty = true;
37	      this.#value = event.target.value;
38	      this.#sync();
39	      this.dispatchEvent(new Event("change", { bubbles: true }));
40	    });
41	    this.#options.addEventListener("input", (event) => {
42	      this.#dirty = true;
43	      this.#value = event.target.value;
44	      this.#sync();
45	    });
46	    this.addEventListener("invalid", (event) => {
47	      if (this.error) event.preventDefault();
48	    });
49	    this.#observer = new MutationObserver((records) => {
50	      if (records.some((record) => record.type === "childList" || record.target !== this))
51	        this.#renderOptions();
52	    });
53	  }
54	
55	  connectedCallback() {
56	    this.#observer.observe(this, {
57	      childList: true,
58	      subtree: true,
59	      attributes: true,
60	      characterData: true,
61	    });
62	    if (!this.#dirty) this.#value = this.getAttribute("value") ?? "";
63	    this.#renderOptions();
64	  }
65	  disconnectedCallback() {
66	    this.#observer.disconnect();
67	  }
68	  attributeChangedCallback(name) {
69	    if (name === "value" && !this.#dirty) this.#value = this.getAttribute("value") ?? "";
