149	    else this.setAttribute(name, value);
150	  }
151	  #renderOptions() {
152	    const focusedValue = this.shadowRoot.activeElement?.value;
153	    this.#options.replaceChildren();
154	    for (const [index, option] of [...this.querySelectorAll(":scope > option")].entries()) {
155	      const choice = document.createElement("label");
156	      choice.className = "choice";
157	      choice.setAttribute("part", "choice");
158	      const input = document.createElement("input");
159	      input.type = "radio";
160	      input.name = "choice";
161	      input.id = `option-${index}`;
162	      input.value = option.value;
163	      input.className = "control";
164	      input.setAttribute("part", "control");
165	      input.dataset.disabled = String(option.disabled);
166	      const box = document.createElement("span");
167	      box.className = "box";
168	      const indicator = document.createElement("span");
169	      indicator.className = "indicator";
170	      indicator.setAttribute("part", "indicator");
171	      indicator.setAttribute("aria-hidden", "true");
172	      box.append(input, indicator);
173	      const text = document.createElement("span");
174	      text.className = "option-label";
175	      text.setAttribute("part", "option-label");
176	      text.textContent = option.label;
177	      choice.append(box, text);
178	      this.#options.append(choice);
179	    }
180	    this.#sync();
181	    if (focusedValue !== undefined) {
182	      const replacement = [...this.#options.querySelectorAll("input")].find(
183	        (input) => input.value === focusedValue && !input.disabled,
184	      );
185	      (replacement ?? this[focusTarget])?.focus();
186	    }
187	  }
188	  #sync() {
189	    const disabled = this.disabled || this.#formDisabled;
190	    const root = this.shadowRoot;
191	    root.querySelector(".field").classList.toggle("is-disabled", disabled);
192	    root.querySelector("#label").textContent = this.label + (this.required ? " *" : "");
193	    this.#options.setAttribute("aria-required", String(this.required));
194	    this.#options.setAttribute("aria-disabled", String(disabled));
195	    this.#options.setAttribute("aria-invalid", String(Boolean(this.error)));
196	    const messages = [];
197	    for (const name of ["hint", "error"]) {
198	      const node = root.querySelector(`#${name}`);
199	      node.textContent = this[name];
200	      node.hidden = !this[name];
201	      if (this[name]) messages.push(name);
202	    }
203	    this.#options.setAttribute("aria-describedby", messages.join(" "));
204	    let selected;
205	    for (const input of this.#options.querySelectorAll("input")) {
206	      input.disabled = disabled || input.dataset.disabled === "true";
207	      input.required = this.required;
208	      input.checked = Boolean(this.#value) && input.value === this.#value && !selected;
209	      input.setAttribute("aria-describedby", messages.join(" "));
210	      input.setAttribute("aria-invalid", String(Boolean(this.error)));
211	      input.closest(".choice").classList.toggle("is-disabled", input.disabled);
212	      if (input.checked) selected = input;
213	    }
214	    this.#internals.setFormValue(
215	      selected && !selected.disabled ? selected.value : null,
216	      this.#value,
217	    );
218	    const anchor = this[focusTarget];
219	    if (disabled) this.#internals.setValidity({});
220	    else if (this.error)
221	      this.#internals.setValidity({ customError: true }, this.error, anchor ?? undefined);
222	    else if (this.required && (!selected || selected.disabled))
223	      this.#internals.setValidity({ valueMissing: true }, "Choose an option.", anchor ?? undefined);
224	    else this.#internals.setValidity({});
225	  }
226	}
